import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Application } from 'src/app/auth/Models/Application';
import { Company } from 'src/app/landing/models/company';
import { Job } from 'src/app/landing/models/job';
import { ApplicationService } from 'src/app/service/application/application.service';
import { CompanyService } from 'src/app/service/company/company.service';
import { JobService } from 'src/app/service/job/job.service';
import { AuthStateService } from 'src/app/shared/services/auth-state.service';

@Component({
  selector: 'app-applicants-list',
  templateUrl: './applicants-list.component.html',
  styleUrls: ['./applicants-list.component.css']
})
export class ApplicantsListComponent implements OnInit {
  company!: Company;
  job!: Job;
  applicants: Application[] = [];

  constructor(
    private readonly compService: CompanyService,
    private readonly appService: ApplicationService,
    private readonly jobService: JobService,
    private readonly route: ActivatedRoute,
    private readonly authState: AuthStateService
  ) {}

  ngOnInit(): void {
    const jobId = Number(this.route.snapshot.paramMap.get('jobId') ?? 0);
    const companyId = Number(this.route.snapshot.paramMap.get('id') ?? this.authState.id ?? 0);

    if (companyId > 0) {
      this.compService.getCompanyById(companyId).subscribe((res: Company) => (this.company = res));
    }
    if (jobId > 0) {
      this.appService.getApplicationByJob(jobId).subscribe((res: Application[]) => (this.applicants = res));
      this.jobService.getJobById(jobId).subscribe((res: Job) => (this.job = res));
    }
  }

  get avatar(): string {
    return this.authState.initialsFromCompany(this.company);
  }
}
